	  //t1->GetBranch( TString(mycopy->At(j)->GetName()) ) -> SetName( TString::Format("branchTemp%d", j) );
	  //t1->Draw( TString::Format("branchTemp%d", j)+" >> h_"+TString::Format("Temp%d", j));
